--
-- Table structure for table `payroll_earning_deduction_types`
--

CREATE TABLE `payroll_earning_deduction_types` (
  `id` int(11) NOT NULL,
  `comp_id` int(11) NOT NULL,
  `item_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_type` enum('earning','deduction') COLLATE utf8mb4_unicode_ci NOT NULL,
  `calculation_method` enum('fixed_amount','percent_of_base_salary','manual_entry') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual_entry',
  `fixed_amount` decimal(15,2) DEFAULT NULL,
  `percent_rate` decimal(5,2) DEFAULT NULL,
  `tax_treatment` enum('taxable','non_taxable') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'earning only',
  `tax_deduction_impact` enum('before_tax','after_tax') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'deduction only',
  `calc_sso` tinyint(1) NOT NULL DEFAULT 0,
  `calc_pf` tinyint(1) NOT NULL DEFAULT 0,
  `country_code` varchar(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NULL = ทุกประเทศ',
  `source_event_code` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ผูกกับเหตุการณ์ attendance เช่น late/absent/early_leave เพื่อให้ Payroll Process ดึงข้อมูลอัตโนมัติ',
  `statutory_report_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'tag ระบุว่า deduction type นี้ต้องรายงานไปหน่วยงานภายนอกตัวไหน เช่น TH_SLF = กยศ. (nullable, deduction only)',
  `is_sync_only` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'true = sync เท่านั้น เช่น trip allowance ห้ามสร้าง/แก้ manual',
  `status` enum('active','inactive','deleted') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

