  `cutoff_use_last_day` tinyint(1) NOT NULL DEFAULT 0,
  `cutoff_day_of_week` enum('monday','tuesday','wednesday','thursday','friday','saturday','sunday') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ใช้เมื่อ payroll_frequency = weekly',
  `payment_day_of_month` tinyint(3) unsigned DEFAULT NULL COMMENT '1-28 เท่านั้น เพื่อให้มีทุกเดือน',
  `payment_use_last_day` tinyint(1) NOT NULL DEFAULT 0,
  `payment_day_of_week` enum('monday','tuesday','wednesday','thursday','friday','saturday','sunday') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ใช้เมื่อ payroll_frequency = weekly',
  `ot_cutoff_type` enum('same_as_attendance','custom') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'same_as_attendance',
  `ot_cutoff_day_of_month` tinyint(3) unsigned DEFAULT NULL COMMENT 'ใช้เมื่อ ot_cutoff_type = custom, 1-28',
  `ot_cutoff_use_last_day` tinyint(1) NOT NULL DEFAULT 0,
  `bank_file_format_id` int(11) DEFAULT NULL,
  `status` enum('active','inactive','deleted') COLLATE utf8mb4_unicode_ci DEFAULT 'active',
