-- actual code paths in the system.
--

CREATE TABLE `approval_document_types` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_approval_doc_type_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


-- --------------------------------------------------------

--
-- Table structure for table `approval_workflows`
--
-- Header record for one configured approval workflow (an ordered set of steps) belonging
-- to a company.
--

CREATE TABLE `approval_workflows` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL,
  `workflow_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive','deleted') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_approval_workflows_comp_status` (`comp_id`,`status`),
  CONSTRAINT `fk_approval_workflows_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `approval_workflow_document_types`
--
-- Many-to-many: which document types a workflow applies to. App layer enforces that a
-- document_type_code maps to at most one ACTIVE workflow per company at a time (cannot be
-- a DB constraint, same reason deleted_at-scoped uniqueness elsewhere in this project can't be).
--

CREATE TABLE `approval_workflow_document_types` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `workflow_id` int(11) NOT NULL,
  `document_type_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_workflow_doc_type` (`workflow_id`,`document_type_code`),
  KEY `idx_awdt_doc_type` (`document_type_code`),
  CONSTRAINT `fk_awdt_workflow` FOREIGN KEY (`workflow_id`) REFERENCES `approval_workflows` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_awdt_doc_type` FOREIGN KEY (`document_type_code`) REFERENCES `approval_document_types` (`code`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `approval_workflow_steps`
--
-- Ordered steps within a workflow. Whole set is replaced (delete+reinsert) on each workflow
-- save, same pattern as employee_earning_deduction_installments — this is config, not history
-- (see approval_request_logs for the history side).
--

CREATE TABLE `approval_workflow_steps` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `workflow_id` int(11) NOT NULL,
  `step_order` int(11) NOT NULL,
  `step_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approver_type` enum('user','role') COLLATE utf8mb4_unicode_ci NOT NULL,
  `approver_id` int(11) NOT NULL COMMENT 'employees.id when approver_type=user, structure_roles.id when approver_type=role. Polymorphic by design, no single FK possible.',
  `joint_approve_mode` enum('any','all') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'any' COMMENT 'Only meaningful when approver_type=role and the role has more than one active employee: all = every current holder must approve this step before it advances, any = the first action decides.',
  `timeout_hours` int(11) DEFAULT NULL COMMENT 'Config-only in this round: no scheduled-job engine exists yet to act on this automatically.',
  `escalation_approver_type` enum('user','role') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `escalation_approver_id` int(11) DEFAULT NULL COMMENT 'Same polymorphic shape as approver_id, config-only (see timeout_hours).',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_workflow_step_order` (`workflow_id`,`step_order`),
  CONSTRAINT `fk_aws_workflow` FOREIGN KEY (`workflow_id`) REFERENCES `approval_workflows` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `approval_requests`
--
-- A running (or completed) instance of a workflow against one real document. Workflow
-- deletion is a soft delete (status=deleted) gated at the app layer by "no pending requests";
-- the RESTRICT FK here is a hard backstop so history can never be silently orphaned regardless
-- of request status.
--

CREATE TABLE `approval_requests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL,
  `workflow_id` int(11) NOT NULL,
  `document_type_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference_id` int(11) NOT NULL COMMENT 'id of the actual document row; meaning depends on document_type_code (e.g. payroll_runs.id for PAYROLL_RUN_APPROVAL). Polymorphic by design, no FK.',
  `reference_label` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Human-readable snapshot (e.g. run name/period) captured at request creation, so the monitor page does not need a different join per document_type_code.',
  `current_step_order` int(11) NOT NULL DEFAULT 1,
  `status` enum('pending','approved','rejected','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `requested_by` int(11) NOT NULL,
  `requested_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_approval_requests_comp_status` (`comp_id`,`status`),
  KEY `idx_approval_requests_reference` (`document_type_code`,`reference_id`),
  CONSTRAINT `fk_ar_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ar_workflow` FOREIGN KEY (`workflow_id`) REFERENCES `approval_workflows` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ar_doc_type` FOREIGN KEY (`document_type_code`) REFERENCES `approval_document_types` (`code`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `approval_request_logs`
--
-- Audit trail of every approve/reject/cancel action taken against an approval_requests row.
-- Same shape as payroll_run_audit_logs.
--

CREATE TABLE `approval_request_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `request_id` int(11) NOT NULL,
  `step_order` int(11) NOT NULL,
  `step_name_snapshot` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Snapshot of step_name at the time of action, so history stays readable even if the step is later edited/reordered.',
  `action` enum('approve','reject','cancel') COLLATE utf8mb4_unicode_ci NOT NULL,
  `acted_by` int(11) NOT NULL,
  `note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `acted_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_arl_request` (`request_id`),
  CONSTRAINT `fk_arl_request` FOREIGN KEY (`request_id`) REFERENCES `approval_requests` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `master_work_locations`
--
-- Per-company work location list (physical work site, e.g. head office / branch site / WFH),
-- deliberately separate from structure_branches (which is a legal/org-structure concept). Exists
-- to finally back employees.work_location_id, which has been a dead column with no master table
-- since the original schema (see its column comment).
--

CREATE TABLE `master_work_locations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL COMMENT 'ID บริษัทที่ล็อกอิน',
  `location_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `location_name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `location_name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive','deleted') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_comp_location_code` (`comp_id`,`location_code`,`deleted_at`),
  KEY `idx_work_locations_tenant` (`comp_id`,`deleted_at`,`status`),
  CONSTRAINT `fk_work_locations_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `shifts`
--
-- Minimal real table for the Shift tab, added only to give holiday_assignments.scope_type='shift'
-- something real to reference. Does not cover the rest of the Shift tab's requirements.
--

CREATE TABLE `shifts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL COMMENT 'ID บริษัทที่ล็อกอิน',
  `shift_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shift_name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shift_name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `break_minutes` int(11) NOT NULL DEFAULT 0,
  `work_location_id` int(11) DEFAULT NULL COMMENT 'default work location for employees on this shift',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive','deleted') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_comp_shift_code` (`comp_id`,`shift_code`,`deleted_at`),
  KEY `idx_shifts_tenant` (`comp_id`,`deleted_at`,`status`),
  KEY `idx_shifts_work_location` (`work_location_id`),
  CONSTRAINT `fk_shifts_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_shifts_work_location` FOREIGN KEY (`work_location_id`) REFERENCES `master_work_locations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `holidays`
--

CREATE TABLE `holidays` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL COMMENT 'ID บริษัทที่ล็อกอิน',
  `country_code` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ต้องตรงกับ companies.registered_country ของบริษัทนี้ เช็คที่ application layer',
  `name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `holiday_date` date NOT NULL COMMENT 'วันที่จริงสำหรับ one-time, หรือวันที่อ้างอิง (ใช้แค่เดือน/วัน) สำหรับ recurring',
  `is_recurring` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = ทุกปี (ใช้เดือน/วันของ holiday_date ซ้ำทุกปี), 0 = เฉพาะปีของ holiday_date เท่านั้น',
  `assignment_mode` enum('include','exclude') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'include' COMMENT 'include = เฉพาะ scope ที่เลือกใน holiday_assignments, exclude = ทุกคนยกเว้น scope ที่เลือก',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive','deleted') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_holidays_tenant` (`comp_id`,`deleted_at`,`status`),
  KEY `idx_holidays_date` (`holiday_date`),
  CONSTRAINT `fk_holidays_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `holiday_assignments`
--
-- Whole set deleted + reinserted on every holiday save, same pattern as approval_workflow_steps /
-- employee_earning_deduction_installments. scope_id is polymorphic (shifts/structure_departments/
-- structure_positions/employees depending on scope_type) validated at the application layer.
--

CREATE TABLE `holiday_assignments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `holiday_id` int(11) NOT NULL,
  `scope_type` enum('shift','department','position','employee') COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope_id` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ha_holiday` (`holiday_id`),
  KEY `idx_ha_scope` (`scope_type`,`scope_id`),
  CONSTRAINT `fk_ha_holiday` FOREIGN KEY (`holiday_id`) REFERENCES `holidays` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `master_leave_categories`
--

CREATE TABLE `master_leave_categories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_th` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_leave_category_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


-- --------------------------------------------------------

--
-- Table structure for table `leave_types`
--

CREATE TABLE `leave_types` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL COMMENT 'ID บริษัทที่ล็อกอิน',
  `category_id` int(11) NOT NULL,
  `code` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quota_type` enum('fixed','prorate') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'fixed',
  `quota_amount` decimal(6,2) NOT NULL DEFAULT 0.00 COMMENT 'จำนวนโควต้าต่อปี หน่วยตาม unit_type',
  `unit_type` enum('day','hour','half_day') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'day',
  `requires_document` tinyint(1) NOT NULL DEFAULT 0,
  `is_continuous` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = นับรวมวันหยุด/วันหยุดนักขัตฤกษ์ที่คั่นระหว่างวันลาด้วย (นับทุกวัน), 0 = นับเฉพาะวันทำงาน',
  `is_paid` tinyint(1) NOT NULL DEFAULT 1,
  `allow_carry_over` tinyint(1) NOT NULL DEFAULT 0,
  `statutory_minimum_days` decimal(6,2) DEFAULT NULL COMMENT 'อ้างอิง master_statutory_leave_minimums ของ country_code บริษัทนี้ ห้ามตั้ง quota_amount ต่ำกว่านี้',
  `gender_restriction` enum('all','male','female') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `min_service_days` int(11) DEFAULT NULL COMMENT 'อายุงานขั้นต่ำก่อนมีสิทธิ์ใช้ลาประเภทนี้ (วัน), NULL = ไม่จำกัด',
  `advance_notice_days` int(11) DEFAULT NULL COMMENT 'ต้องแจ้งล่วงหน้าก่อนวันลากี่วัน, NULL = ไม่จำกัด',
  `max_consecutive_days` decimal(6,2) DEFAULT NULL COMMENT 'จำนวนวันสูงสุดต่อการลา 1 ครั้ง, NULL = ไม่จำกัด',
  `applicable_employment_statuses` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CSV ของ employees.employment_status ที่มีสิทธิ์ เช่น "permanent,contract"; NULL = ทุกสถานะ',
  `status` enum('active','inactive','deleted') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_comp_leave_code` (`comp_id`,`code`,`deleted_at`),
  KEY `idx_leave_types_tenant` (`comp_id`,`deleted_at`,`status`),
  KEY `idx_leave_types_category` (`category_id`),
  CONSTRAINT `fk_leave_types_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_leave_types_category` FOREIGN KEY (`category_id`) REFERENCES `master_leave_categories` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `master_statutory_leave_minimums`
--
-- Global reference table (not per-company) used only to validate that a company's leave_types.statutory_minimum_days
-- isn't set below the legal floor for its country. Seed values below are DRAFT / NOT verified against the official
-- statute text in this environment -- do not treat as legal advice. SG/MY intentionally left unseeded here because
-- their statutory annual leave is a tenure-based sliding scale (a single flat floor would misrepresent the law).
-- US intentionally left empty -- no federal statutory minimum, varies by state.
--

CREATE TABLE `master_statutory_leave_minimums` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `country_code` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_id` int(11) NOT NULL,
  `min_days` decimal(6,2) NOT NULL,
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_country_category` (`country_code`,`category_id`),
  CONSTRAINT `fk_msl_category` FOREIGN KEY (`category_id`) REFERENCES `master_leave_categories` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


-- --------------------------------------------------------

--
-- Table structure for table `permissions`
--
-- Global (not per-company) master list of system capabilities, module_code + action_code pair.
--

CREATE TABLE `permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `module_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `action_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `permission_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'module_code.action_code เช่น holiday.manage',
  `name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_permission_key` (`permission_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


-- --------------------------------------------------------

--
-- Table structure for table `role_permissions`
--
-- Links structure_roles (existing role table) to permissions. No new roles/user_roles table --
-- employees.role_id already provides the one-role-per-employee link.
--

CREATE TABLE `role_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `role_id` int(11) NOT NULL,
  `permission_id` int(11) NOT NULL,
  `allow_scope` enum('all','own_department') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_role_permission` (`role_id`,`permission_id`),
  KEY `idx_rp_permission` (`permission_id`),
  CONSTRAINT `fk_rp_role` FOREIGN KEY (`role_id`) REFERENCES `structure_roles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_rp_permission` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `master_payslip_field_types`
--
-- Global (not per-company) master list of payslip fields a template can toggle on/off. 'earning'
-- and 'deduction' groups only include the two block-level catch-all rows (earning_lines_all /
-- deduction_lines_all) -- individual earning/deduction TYPES (OT, trip allowance, etc.) are an
-- open, per-company-growable set (payroll_earning_deduction_types), not enumerable here, so a
-- template shows a whole breakdown block rather than picking specific item codes.
--

CREATE TABLE `master_payslip_field_types` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_group` enum('employee_info','company_info','earning','deduction','statutory','summary') COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payslip_field_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


-- --------------------------------------------------------

--
-- Table structure for table `payslip_templates`
--

CREATE TABLE `payslip_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL COMMENT 'ID บริษัทที่ล็อกอิน',
  `country_code` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ต้องตรงกับ companies.registered_country ของบริษัทนี้ เช็คที่ application layer',
  `name_th` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'ใช้ template นี้อัตโนมัติตอน generate PAY_SLIP ถ้าไม่ระบุ ต้องมีได้แค่ 1 active default ต่อบริษัท เช็คที่ application layer',
  `logo_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'เก็บที่ template ไม่ใช่ companies เพราะ companies ไม่มีคอลัมน์ logo',
  `header_text_th` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `header_text_en` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `footer_text_th` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `footer_text_en` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `language_mode` enum('th','en','both') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'both',
  `status` enum('active','inactive','deleted') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_payslip_templates_tenant` (`comp_id`,`deleted_at`,`status`),
  CONSTRAINT `fk_payslip_templates_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `payslip_template_fields`
--
-- Whole set deleted + reinserted on every template save, same pattern as holiday_assignments /
-- approval_workflow_steps. sort_order is derived from array position client-side, never trusted
-- from the client directly.
--

CREATE TABLE `payslip_template_fields` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `template_id` int(11) NOT NULL,
  `field_key` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'references master_payslip_field_types.code, validated at application layer',
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `custom_label_th` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'optional override of master_payslip_field_types.name_th for this template',
  `custom_label_en` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ptf_template` (`template_id`),
  CONSTRAINT `fk_ptf_template` FOREIGN KEY (`template_id`) REFERENCES `payslip_templates` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------
-- Table structure for table `master_notification_channels`
-- Global master (not per-company) for outbound payslip delivery channels, same
-- fixed-but-growable-set convention as `master_ot_scope_types`. Adding a new channel
-- (e.g. WhatsApp) later = insert a row + write a NotificationChannelInterface class,
-- no ALTER needed.
-- --------------------------------------------------------

CREATE TABLE `master_notification_channels` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_th` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_en` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_notification_channel_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;


-- --------------------------------------------------------
-- Table structure for table `payslip_distribution_settings`
-- Singleton config per company (one active row per comp_id) -- not a deletable list,
-- so `is_active` is a simple toggle rather than the full status/deleted_at soft-delete
-- pattern used for record lists elsewhere in this project.
-- --------------------------------------------------------

CREATE TABLE `payslip_distribution_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL,
  `distribution_mode` enum('auto','request_only','both') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'request_only',
  `send_delay_hours` int(11) NOT NULL DEFAULT 0 COMMENT 'ใช้เฉพาะโหมด auto/both, 0 = ส่งทันทีเมื่อ run เข้าสถานะ paid',
  `scope_department_ids` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CSV ของ structure_departments.id ที่ auto-send ใช้ได้, NULL/ว่าง = ทุกแผนก',
  `scope_employment_statuses` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CSV ของ employees.employment_status ที่ auto-send ใช้ได้, NULL/ว่าง = ทุกสถานะ',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payslip_distribution_settings_comp` (`comp_id`),
  CONSTRAINT `fk_pds_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------
-- Table structure for table `payslip_distribution_channels`
-- Ordered channel + fallback chain per company setting. Whole set deleted + reinserted
-- on every settings save, same pattern as `holiday_assignments` / `approval_workflow_steps`.
-- --------------------------------------------------------

CREATE TABLE `payslip_distribution_channels` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `setting_id` int(11) NOT NULL,
  `channel_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'references master_notification_channels.code, validated at application layer',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '1 = ช่องทางหลัก, 2 = fallback แรก, 3 = fallback ถัดไป ...',
  PRIMARY KEY (`id`),
  KEY `idx_pdc_setting` (`setting_id`),
  CONSTRAINT `fk_pdc_setting` FOREIGN KEY (`setting_id`) REFERENCES `payslip_distribution_settings` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------
-- Table structure for table `payslip_requests`
-- Mode B: employee-initiated payslip request. Created together with its
-- `approval_requests` row (document_type_code = 'SLIP_REQUEST_APPROVAL'). approval_request_id
-- is nullable only for the instant between inserting this row and creating the linked
-- approval_requests row within the same transaction (reference_id on that side points back to
-- this row's id, so this row must exist first) -- PayslipRequestModel::create() always fills it
-- in before commit, and rolls back the whole thing (never leaving an orphan) if no active
-- workflow is mapped to SLIP_REQUEST_APPROVAL for the company.
-- --------------------------------------------------------

CREATE TABLE `payslip_requests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL COMMENT 'พนักงานเจ้าของสลิปที่ขอ',
  `run_id` int(11) NOT NULL COMMENT 'งวด payroll ที่ขอสลิป',
  `requested_by` int(11) NOT NULL COMMENT 'employees.id ของผู้กดขอจริง (ตอนนี้คือ HR กดแทน, อนาคตอาจเป็นตัวพนักงานเองผ่าน portal)',
  `approval_request_id` int(11) DEFAULT NULL,
  `selected_channel` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'เลือกตอนอนุมัติ - NULL = ใช้ employees.default_payslip_channel ตอนส่งจริง, references master_notification_channels.code',
  `status` enum('pending','approved','rejected','cancelled','sent','send_failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payslip_requests_approval_request` (`approval_request_id`),
  KEY `idx_payslip_requests_lookup` (`comp_id`,`employee_id`,`run_id`),
  CONSTRAINT `fk_pr_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_run` FOREIGN KEY (`run_id`) REFERENCES `payroll_runs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pr_approval_request` FOREIGN KEY (`approval_request_id`) REFERENCES `approval_requests` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------
-- Table structure for table `payslip_delivery_logs`
-- Every send attempt across both modes (auto + request), including each hop of a
-- fallback chain, and manual HR resends. Audit-only: log/list, no update/delete,
-- same convention as `payroll_run_audit_logs`.
-- --------------------------------------------------------

CREATE TABLE `payslip_delivery_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `comp_id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `run_id` int(11) NOT NULL,
  `source` enum('auto','request') COLLATE utf8mb4_unicode_ci NOT NULL,
  `payslip_request_id` int(11) DEFAULT NULL COMMENT 'เฉพาะ source=request',
  `channel_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'references master_notification_channels.code',
  `attempt_order` int(11) NOT NULL DEFAULT 1 COMMENT 'ลำดับใน fallback chain ของการส่งครั้งนี้ (1=ช่องทางหลัก)',
  `recipient` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ปลายทางจริงที่ใช้ส่ง (email address / LINE user id / telegram chat id)',
  `status` enum('success','failed') COLLATE utf8mb4_unicode_ci NOT NULL,
  `error_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sent_by` int(11) DEFAULT NULL COMMENT 'NULL = ระบบส่งอัตโนมัติ, มีค่า = HR สั่ง resend เอง',
  `sent_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pdl_lookup` (`comp_id`,`employee_id`,`run_id`),
  KEY `idx_pdl_request` (`payslip_request_id`),
  CONSTRAINT `fk_pdl_company` FOREIGN KEY (`comp_id`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pdl_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_pdl_run` FOREIGN KEY (`run_id`) REFERENCES `payroll_runs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pdl_request` FOREIGN KEY (`payslip_request_id`) REFERENCES `payslip_requests` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------
-- employees: Telegram recipient id (line_id already existed; telegram had no equivalent column
-- anywhere -- added for TelegramChannel's recipient resolution, even though that channel is a
-- stub for now) + default delivery channel preference (settable by HR in Employee Detail for now,
-- until real employee self-service exists)
-- --------------------------------------------------------

ALTER TABLE `employees`
  ADD COLUMN `telegram_chat_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL AFTER `line_id`;

ALTER TABLE `employees`
  ADD COLUMN `default_payslip_channel` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'references master_notification_channels.code, validated at application layer' AFTER `telegram_chat_id`;

